/**
 * AI + IoT Smart Energy Consumption Prediction
 * Data Service
 * 
 * Responsible for loading authentic ML output and communicating with the
 * trained LSTM prediction backend API (/api/feed, /api/forecast, /api/predict).
 * 
 * Strict Anti-Mock Policy:
 * - Uses actual inferences generated by the trained LSTM model
 * - Reports exact, actionable error messages
 * - Provides retry capabilities without crashing the UI
 */

const getApiBaseUrl = () => {
  if (typeof window !== 'undefined' && window.__API_URL__) {
    return window.__API_URL__;
  }
  return '';
};

class DataService {
  constructor() {
    this.apiBaseUrl = getApiBaseUrl();
    this.forecastData = null;
    this.evaluationMetrics = null;
    this.testPredictions = []; // Array of authentic observations
    this.isLiveApi = false;
    this.loading = {
      forecast: false,
      metrics: false,
      csv: false,
      liveInference: false
    };
    this.errors = {
      forecast: null,
      metrics: null,
      csv: null,
      liveInference: null
    };
    this.listeners = new Set();
    this.pollingTimer = null;
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  notify(isUpdate = false) {
    const state = this.getState();
    this.listeners.forEach(fn => fn(state, isUpdate));
  }

  getState() {
    return {
      forecastData: this.forecastData,
      evaluationMetrics: this.forecastData?.evaluation_metrics || this.evaluationMetrics,
      testPredictions: this.testPredictions,
      isLiveApi: this.isLiveApi,
      loading: { ...this.loading },
      errors: { ...this.errors },
      hasErrors: Boolean(this.errors.forecast || this.errors.metrics || this.errors.csv),
      failedFiles: this.getFailedFiles()
    };
  }

  getFailedFiles() {
    const list = [];
    if (this.errors.forecast) {
      list.push({ file: 'forecast_data.json / /api/feed', error: this.errors.forecast });
    }
    if (this.errors.metrics) {
      list.push({ file: 'evaluation_metrics.json / /api/metrics', error: this.errors.metrics });
    }
    if (this.errors.csv) {
      list.push({ file: 'test_predictions.csv', error: this.errors.csv });
    }
    return list;
  }

  async loadForecastData() {
    this.loading.forecast = true;
    this.notify();

    // Strategy 1: Attempt to load from live LSTM Backend API /api/feed
    try {
      const apiUrl = `${this.apiBaseUrl}/api/feed?steps=60&_t=${Date.now()}`;
      const res = await fetch(apiUrl, { cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        this.forecastData = data;
        this.isLiveApi = true;
        this.errors.forecast = null;
        if (data.evaluation_metrics) {
          this.evaluationMetrics = data.evaluation_metrics;
          this.errors.metrics = null;
        }
        this.loading.forecast = false;
        this.notify();
        return;
      }
    } catch {
      // Fall through to static file strategy
    }

    // Strategy 2: Fall back to static forecast_data.json
    try {
      const path = `AI_IoT_Project/results/forecast_data.json?_t=${Date.now()}`;
      const res = await fetch(path, { cache: 'no-store' });
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }
      const data = await res.json();
      this.forecastData = data;
      this.isLiveApi = false;
      this.errors.forecast = null;
      if (data.evaluation_metrics) {
        this.evaluationMetrics = data.evaluation_metrics;
        this.errors.metrics = null;
      }
    } catch (err) {
      console.error('[DataService] Failed to load forecast data:', err);
      this.forecastData = null;
      this.errors.forecast = 'Unable to load forecast data. Please verify that the backend API or ML results directory is available.';
    } finally {
      this.loading.forecast = false;
      this.notify();
    }
  }

  async generateLiveForecast(steps = 60) {
    this.loading.liveInference = true;
    this.errors.liveInference = null;
    this.notify();

    try {
      const url = `${this.apiBaseUrl}/api/forecast?steps=${steps}&_t=${Date.now()}`;
      const res = await fetch(url, { cache: 'no-store' });
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }
      const data = await res.json();
      if (data.future_forecast && this.forecastData) {
        this.forecastData = {
          ...this.forecastData,
          future_forecast_60min: data.future_forecast,
          forecast_horizon_minutes: steps
        };
        this.isLiveApi = true;
      }
      return data.future_forecast;
    } catch (err) {
      console.error('[DataService] Live forecast generation failed:', err);
      this.errors.liveInference = err.message || 'Live inference failed';
      throw err;
    } finally {
      this.loading.liveInference = false;
      this.notify(true);
    }
  }

  async predictSequence(sequence30x5) {
    try {
      const url = `${this.apiBaseUrl}/api/predict`;
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sequence: sequence30x5 })
      });
      if (!res.ok) {
        const errJson = await res.json().catch(() => ({}));
        throw new Error(errJson.error || `HTTP ${res.status}`);
      }
      return await res.json();
    } catch (err) {
      console.error('[DataService] predictSequence failed:', err);
      throw err;
    }
  }

  async loadEvaluationMetrics() {
    this.loading.metrics = true;
    this.notify();

    // Try API first
    try {
      const res = await fetch(`${this.apiBaseUrl}/api/metrics`);
      if (res.ok) {
        this.evaluationMetrics = await res.json();
        this.errors.metrics = null;
        this.loading.metrics = false;
        this.notify();
        return;
      }
    } catch {
      // Fallback
    }

    const path = 'AI_IoT_Project/results/evaluation_metrics.json';
    try {
      const res = await fetch(path);
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }
      const data = await res.json();
      this.evaluationMetrics = data;
      this.errors.metrics = null;
    } catch (err) {
      console.warn('[DataService] Failed to load evaluation_metrics.json directly:', err);
      if (this.forecastData?.evaluation_metrics) {
        this.evaluationMetrics = this.forecastData.evaluation_metrics;
        this.errors.metrics = null;
      } else {
        this.evaluationMetrics = null;
        this.errors.metrics = 'Unable to load evaluation_metrics.json. Please verify that the ML results directory is available.';
      }
    } finally {
      this.loading.metrics = false;
      this.notify();
    }
  }

  async loadTestPredictionsCsv() {
    const path = 'AI_IoT_Project/results/test_predictions.csv';
    this.loading.csv = true;
    this.notify();

    try {
      const res = await fetch(path);
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }
      const csvText = await res.text();
      this.testPredictions = this.parseCsv(csvText);
      this.errors.csv = null;
    } catch (err) {
      console.error('[DataService] Failed to load test_predictions.csv:', err);
      this.testPredictions = [];
      this.errors.csv = 'Unable to load test_predictions.csv. Please verify that the ML results directory is available.';
    } finally {
      this.loading.csv = false;
      this.notify();
    }
  }

  parseCsv(csvText) {
    const lines = csvText.split('\n');
    const records = [];
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;
      const parts = line.split(',');
      if (parts.length >= 4) {
        records.push({
          index: i,
          timestamp: parts[0],
          actual_power_w: parseFloat(parts[1]),
          predicted_power_w: parseFloat(parts[2]),
          error_w: parseFloat(parts[3])
        });
      }
    }
    return records;
  }

  async loadAll() {
    await Promise.all([
      this.loadForecastData(),
      this.loadEvaluationMetrics(),
      this.loadTestPredictionsCsv()
    ]);
  }

  async retryFailed() {
    const promises = [];
    if (this.errors.forecast) promises.push(this.loadForecastData());
    if (this.errors.metrics) promises.push(this.loadEvaluationMetrics());
    if (this.errors.csv) promises.push(this.loadTestPredictionsCsv());
    await Promise.all(promises);
  }

  startPolling(intervalMs = 8000) {
    if (this.pollingTimer) clearInterval(this.pollingTimer);
    this.pollingTimer = setInterval(async () => {
      await this.checkForUpdates();
    }, intervalMs);
  }

  stopPolling() {
    if (this.pollingTimer) {
      clearInterval(this.pollingTimer);
      this.pollingTimer = null;
    }
  }

  async checkForUpdates() {
    try {
      const apiUrl = `${this.apiBaseUrl}/api/feed?steps=60&_t=${Date.now()}`;
      const res = await fetch(apiUrl, { cache: 'no-store' });
      if (res.ok) {
        const newJson = await res.json();
        const oldMetrics = JSON.stringify(this.forecastData?.evaluation_metrics);
        const newMetrics = JSON.stringify(newJson?.evaluation_metrics);

        this.forecastData = newJson;
        this.isLiveApi = true;
        this.errors.forecast = null;
        if (newJson.evaluation_metrics) {
          this.evaluationMetrics = newJson.evaluation_metrics;
          this.errors.metrics = null;
        }

        if (oldMetrics !== newMetrics) {
          this.notify(true);
        }
        return;
      }
    } catch {
      // Fallback to static polling
    }

    const path = `AI_IoT_Project/results/forecast_data.json?_t=${Date.now()}`;
    try {
      const res = await fetch(path, { cache: 'no-store' });
      if (!res.ok) return;
      const newJson = await res.json();
      const oldMetrics = JSON.stringify(this.forecastData?.evaluation_metrics);
      const newMetrics = JSON.stringify(newJson?.evaluation_metrics);

      this.forecastData = newJson;
      this.errors.forecast = null;
      if (newJson.evaluation_metrics) {
        this.evaluationMetrics = newJson.evaluation_metrics;
        this.errors.metrics = null;
      }

      if (oldMetrics !== newMetrics) {
        this.notify(true);
      }
    } catch {
      // Quietly continue background polling
    }
  }

  computeErrorDistributionBins(step = 2, min = -24, max = 24) {
    const errors = this.testPredictions.map(d => d.error_w);
    if (errors.length === 0) return { labels: [], counts: [], binInfo: [], total: 0 };

    const binCount = Math.floor((max - min) / step);
    const counts = new Array(binCount).fill(0);
    const labels = [];
    const binInfo = [];

    let leftTail = 0;
    let rightTail = 0;

    for (let i = 0; i < binCount; i++) {
      const low = min + i * step;
      const high = low + step;
      const mid = (low + high) / 2;

      let label = '';
      if (low === 0) label = `0 to +${high}W`;
      else if (high === 0) label = `${low} to 0W`;
      else if (low > 0) label = `+${low} to +${high}W`;
      else label = `${low} to ${high}W`;

      labels.push(label);
      binInfo.push({
        low,
        high,
        mid,
        isZero: low <= 0 && high >= 0,
        type: mid > 0 ? 'under' : (mid < 0 ? 'over' : 'exact')
      });
    }

    errors.forEach(err => {
      if (err < min) {
        leftTail++;
      } else if (err >= max) {
        rightTail++;
      } else {
        const binIdx = Math.floor((err - min) / step);
        if (binIdx >= 0 && binIdx < binCount) {
          counts[binIdx]++;
        }
      }
    });

    return {
      labels,
      counts,
      binInfo,
      leftTail,
      rightTail,
      total: errors.length
    };
  }
}

export const dataService = new DataService();
export default dataService;
